        if sum(b - a + 1 for a, b in col_runs[c]) >= 5
    }

    keep = [[False] * w for _ in range(h)]

    # Keep existing horizontal and vertical strokes, and marks aligned
    # with a prominent row or column.
    for r, rs in enumerate(row_runs):
        for a, b in rs:
            if b > a:
                for c in range(a, b + 1):
                    keep[r][c] = True
    for c, rs in enumerate(col_runs):
        for a, b in rs:
            if b > a:
                for a0, b0 in rs:
                    for r in range(a0, b0 + 1):
                        keep[r][c] = True
    for r in range(h):
        for c in range(w):
            if grid[r][c] == fg and (r in major_rows or c in major_cols):
                keep[r][c] = True

    # Fill short gaps in horizontal strokes anchored on a prominent column.
    for r in range(h):
        if not any(grid[r][c] == fg and c in major_cols for c in range(w)):
            continue
        rs = row_runs[r]
        for (a, b), (x, y) in zip(rs, rs[1:]):
            if 1 < x - b <= 4:
                for c in range(b, x + 1):
                    keep[r][c] = True

    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if keep[r][c]:
                out[r][c] = fg
    return out
